// ── Component ─────────────────────────────────────────────────────────────────

interface Props {
  item: MediaItem;
  apiKey: string;
  onClose: () => void;
  onLibraryChange?: () => void;
}

function ProviderRow({ label, providers, link }: { label: string; providers: WatchProvider[]; link?: string }) {
  if (!providers.length) return null;
  return (
    <div>
      <SectionTitle>{label}</SectionTitle>
      <ProvidersGrid>
        {providers.map((p) => {
          const bg = PROVIDER_COLORS[p.provider_name] ?? theme.colors.surface;
          return (
            <ProviderBadge key={p.provider_id} bg={bg} href={link ?? '#'} target="_blank" rel="noreferrer">
              {p.logo_path && (
                <ProviderLogo src={logoUrl(p.logo_path)} alt={p.provider_name} />
              )}
              <ProviderName>{p.provider_name}</ProviderName>
            </ProviderBadge>
          );
        })}
      </ProvidersGrid>
    </div>
  );
}

export function DetailModal({ item, apiKey, onClose, onLibraryChange }: Props) {
  const [detail, setDetail] = useState<MediaDetail | null>(null);
  const [videos, setVideos] = useState<VideoResult[]>([]);
  const [providers, setProviders] = useState<WatchProviders | null>(null);
  const [loading, setLoading] = useState(true);
  const [fav, setFav] = useState(() => isFavorite(item));
  const [seen, setSeen] = useState(() => isSeen(item));

  useEffect(() => {
    setLoading(true);
    Promise.all([
      getDetail(apiKey, item.media_type, item.id),
      getVideos(apiKey, item.media_type, item.id),
      getWatchProviders(apiKey, item.media_type, item.id),
    ]).then(([d, v, p]) => {
      setDetail(d);
      setVideos(v);
      setProviders(p);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [item.id, item.media_type, apiKey]);

  const handleBackdropClick = useCallback(
    (e: React.MouseEvent) => { if (e.target === e.currentTarget) onClose(); },
    [onClose],
  );

  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [onClose]);

  const trailer = videos.find(
    (v) => v.site === 'YouTube' && (v.type === 'Trailer' || v.type === 'Teaser') && v.official,
  ) ?? videos.find((v) => v.site === 'YouTube' && v.type === 'Trailer')
    ?? videos.find((v) => v.site === 'YouTube');

  const handleFav = () => {
    toggleFavorite(item);
    setFav(!fav);
    onLibraryChange?.();
  };

  const handleSeen = () => {
    toggleSeen(item);
    setSeen(!seen);
    onLibraryChange?.();
  };

  const title = mediaTitle(item);
  const year = mediaYear(item);

  const allFlatrate = [
    ...(providers?.flatrate ?? []),
  ].filter((p, i, arr) => arr.findIndex((x) => x.provider_id === p.provider_id) === i);

  const allRent = (providers?.rent ?? []).filter(
    (p) => !allFlatrate.find((f) => f.provider_id === p.provider_id),
  );

  const hasStream = allFlatrate.length > 0 || allRent.length > 0 || (providers?.buy ?? []).length > 0;

  return (
    <Backdrop onClick={handleBackdropClick}>
      <Sheet>
        {/* Close */}
        <div style={{ position: 'relative' }}>
          <CloseBtn onClick={onClose} aria-label="Close">
            <X size={18} />
          </CloseBtn>

          {/* Backdrop image */}
          <BackdropImg
            src={backdropUrl(item.backdrop_path ?? detail?.backdrop_path ?? null, 'w1280')}
          />
        </div>

        {/* Body */}
        <Body>
          {(detail?.poster_path ?? item.poster_path) && (
            <Poster
              src={posterUrl(detail?.poster_path ?? item.poster_path, 'w342')}
              alt={title}
            />
          )}
          <InfoSection>
            <Title>{title}</Title>
            {detail?.tagline && <Tagline>{detail.tagline}</Tagline>}

            <MetaRow>
              <RatingBadge>
                <Star size={14} fill="currentColor" />
                {item.vote_average.toFixed(1)}
              </RatingBadge>
              {year && (
                <MetaItem>
                  <Calendar size={13} />
                  {year}
                </MetaItem>
              )}
              {detail?.runtime && (
                <MetaItem>
                  <Clock size={13} />
                  {Math.floor(detail.runtime / 60)}h {detail.runtime % 60}m
                </MetaItem>
              )}
              {detail?.number_of_seasons && (
                <MetaItem>
                  <Tv size={13} />
                  {detail.number_of_seasons} season{detail.number_of_seasons !== 1 ? 's' : ''}
                </MetaItem>
              )}
            </MetaRow>

            {detail?.genres && detail.genres.length > 0 && (
              <GenreList>
                {detail.genres.map((g) => (
                  <Genre key={g.id}>{g.name}</Genre>
                ))}
              </GenreList>
            )}

            {loading ? (
              <LoadingRow>Loading details…</LoadingRow>
            ) : (
              <OverviewText>{item.overview}</OverviewText>
            )}
          </InfoSection>
        </Body>

        {/* Action buttons: favorite / seen */}
        <ActionRow>
          <ActionBtn active={fav} onClick={handleFav}>
            <Heart size={14} fill={fav ? 'currentColor' : 'none'} />
            {fav ? 'Favorited' : 'Add to Favorites'}
          </ActionBtn>
          <ActionBtn active={seen} onClick={handleSeen}>
            {seen ? <EyeOff size={14} /> : <Eye size={14} />}
            {seen ? 'Mark as Unseen' : 'Mark as Seen'}
          </ActionBtn>
          {(fav || seen) && (
            <ActionBtn
              danger
              onClick={() => {
                if (fav) { toggleFavorite(item); setFav(false); }
                if (seen) { toggleSeen(item); setSeen(false); }
                onLibraryChange?.();
              }}
            >
              <Trash2 size={14} />
              Remove from Library
            </ActionBtn>
          )}
        </ActionRow>

        {/* Trailer */}
        {trailer && (
          <>
            <Divider />
            <TrailerSection>
              <SectionTitle>Trailer</SectionTitle>
              <TrailerFrame>
                <iframe
                  src={`https://www.youtube.com/embed/${trailer.key}?autoplay=0&rel=0`}
                  title={trailer.name}
                  allowFullScreen
                  allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                />
              </TrailerFrame>
            </TrailerSection>
          </>
        )}

        {/* Streaming */}
        <Divider style={{ marginTop: theme.spacing.lg }} />
        <StreamSection>
          <SectionTitle>Where to Watch</SectionTitle>
          {loading ? (
            <LoadingRow>Loading streaming info…</LoadingRow>
          ) : hasStream ? (
            <>
              <ProviderRow
                label="Streaming (Included with subscription)"
                providers={allFlatrate}
                link={providers?.link}
              />
              <ProviderRow label="Rent" providers={allRent} link={providers?.link} />
              <ProviderRow
                label="Buy"
                providers={providers?.buy ?? []}
                link={providers?.link}
              />
            </>
          ) : (
            <NoStream>No streaming info available for your region (US).</NoStream>
          )}
        </StreamSection>

        <div style={{ height: theme.spacing.xxl }} />
      </Sheet>
    </Backdrop>
  );
}
